import { existsSync, mkdirSync } from 'fs';
import { readFile, writeFile } from 'fs/promises';
import { createServer } from 'net';
import { join, resolve } from 'path';
import { Command } from 'commander';
import { ensureAuthenticated } from '../../auth/index.js';
import { getFabricSettings } from '../../config/constants.js';
import { loadRayfinConfig } from '../../utils/config-utils.js';
import { getActiveDeployment } from '../../utils/deployments-registry.js';
import { upsertEnvVariables } from '../../utils/env-file-utils.js';
import { detectFrontendFramework } from '../../utils/frontend-detect.js';
import { inspectFunctionsPrereqs, planFunctionsInstall, formatPrereqsReport, promptAndInstall, refreshPathFromOs, } from '../../utils/functions-prereqs.js';
import { spawnSafe } from '../../utils/platform-utils.js';
